arguments.command:
cat > src/CheckoutPricing.Application/Checkout.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier { Standard, Gold }

public static class Checkout
{
    public static decimal CalculatePayableTotal(CustomerTier tier, decimal subtotal) => subtotal;
}
E
cat > tests/CheckoutPricing.UnitTests/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests;

public class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_subtotal_pays_95()
    {
        Assert.Equal(95.00m, Checkout.CalculatePayableTotal(CustomerTier.Gold, 100.00m));
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | grep -E "error|Assert|Expected|Actual|Failed|Passed!" | head

